import json
with open('/root/autodl-tmp/eval_results/eval_safelibero_object_all_levelII_30000_lora_baseline_seed7.json') as f:
    d = json.load(f)
summary = d.get('summary', d)
print('Keys:', list(d.keys())[:10])
if 'summary' in d:
    print('Summary keys:', list(summary.keys()))
for k in ['avg_TSR', 'avg_CAR', 'frozen_rate', 'total_episodes', 'avg_max_displacement']:
    if k in summary:
        print(f'{k}: {summary[k]}')
    elif k in d:
        print(f'{k}: {d[k]}')
# per-task
if 'tasks' in d:
    for t in d['tasks']:
        name = t.get('task_name', t.get('task_id', '?'))
        print(f\"Task {name}: TSR={t.get('TSR')}, CAR={t.get('CAR')}, disp={t.get('avg_max_displacement')}, frozen={t.get('frozen_rate', t.get('frozen_episodes', 'N/A'))}\")
elif 'per_task' in d:
    for k,v in d['per_task'].items():
        print(f'Task {k}: {v}')
